import os
from azure.core.credentials import AzureKeyCredential
from azure.ai.formrecognizer import DocumentAnalysisClient

def extract_invoice_data(invoice_path: str) -> dict:
    endpoint = os.environ.get("AZURE_FORM_RECOGNIZER_ENDPOINT")
    key = os.environ.get("AZURE_FORM_RECOGNIZER_KEY")

    if not endpoint or not key:
        raise ValueError("AZURE_FORM_RECOGNIZER_ENDPOINT and AZURE_FORM_RECOGNIZER_KEY environment variables must be set.")

    document_analysis_client = DocumentAnalysisClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    with open(invoice_path, "rb") as f:
        poller = document_analysis_client.begin_analyze_document(
            "prebuilt-invoice", document=f.read()
        )
        invoices = poller.result()

    extracted_data = {
        "vendor_name": None,
        "invoice_date": None,
        "total_amount": None,
        "line_items": []
    }

    if invoices.documents:
        invoice = invoices.documents[0]

        if invoice.fields.get("VendorName"):
            extracted_data["vendor_name"] = invoice.fields["VendorName"].value

        if invoice.fields.get("InvoiceDate"):
            extracted_data["invoice_date"] = str(invoice.fields["InvoiceDate"].value) # Convert date object to string

        if invoice.fields.get("InvoiceTotal"):
            extracted_data["total_amount"] = invoice.fields["InvoiceTotal"].value.amount

        if invoice.fields.get("Items"):
            for item in invoice.fields["Items"].value:
                line_item = {}
                if item.value.get("Description"):
                    line_item["description"] = item.value["Description"].value
                if item.value.get("Quantity"):
                    line_item["quantity"] = item.value["Quantity"].value
                if item.value.get("UnitPrice"):
                    line_item["unit_price"] = item.value["UnitPrice"].value
                if item.value.get("Amount"):
                    line_item["amount"] = item.value["Amount"].value
                extracted_data["line_items"].append(line_item)

    return extracted_data
